def __init__(self, store: SqliteJobStore, counter) -> None:
    self.store = store
    self.counter = counter

# ---------- 主循环 ----------

def run_once(self) -> dict | None:
    claimed = self.store.claim_job(worker_id="d-worker", now=datetime.now(UTC))
    if claimed is None:
        return None
    job = claimed["job"]
    lease = claimed["lease"]
    job_type = job["type"]
    try:
        if job_type == "knowledge_index":
            result = self._run_knowledge_index(job["payload"], lease)
        elif job_type == "video_analysis":
            result = self._run_video_analysis(job["payload"], lease)
        elif job_type == "knowledge_reindex":
            result = self._run_knowledge_reindex(job["payload"], lease)
        else:
            raise RuntimeError(f"不支持的作业类型：{job_type}")
    except Exception as exc:  # noqa: BLE001 —— 单作业失败不拖垮 worker
        logger.exception("作业 %s 失败", lease.job_id)
        self.store.fail_job(lease, str(exc), now=datetime.now(UTC))
        if job_type == "video_analysis":
            self.store.fail_video_analysis(job["payload"].get("analysis_id", ""), str(exc))

@contextmanager
def write(self):
    with self._lock:
        conn = self._connect()
        try:
            yield self  # uow 即 store 自身；方法内部各自开短事务
            conn.commit()
        finally:
            conn.close()

def complete_job(self, lease: Any, result: dict[str, Any], now: datetime | None = None) -> dict[str, Any]:
    finished = _iso(now) or _now_iso()
    processed = result.get("chunk_count", result.get("window_count"))
    with self._lock, self._connect() as conn:
        conn.execute(
            "UPDATE d_jobs SET status = 'succeeded', finished_at = ?, processed_count = ?,"
            " lease_token = NULL, lease_expires_at = NULL WHERE id = ?",
            (finished, processed, lease["job_id"] if not isinstance(lease, str) else lease),
        )
    return {"status": "succeeded"}

